import{_ as a,c as o,o as t,az as l}from"./chunks/framework.CAkcY2eT.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"resources/changelog.md","filePath":"resources/changelog.md","lastUpdated":null}'),r={name:"resources/changelog.md"};function i(d,e,s,n,c,u){return t(),o("div",null,e[0]||(e[0]=[l('<h1 id="Changelog" tabindex="-1">Changelog <a class="header-anchor" href="#Changelog" aria-label="Permalink to &quot;Changelog {#Changelog}&quot;">​</a></h1><h2 id="3.7.1-2026-09-04" tabindex="-1">3.7.1 - 2026-09-04 <a class="header-anchor" href="#3.7.1-2026-09-04" aria-label="Permalink to &quot;3.7.1 - 2026-09-04 {#3.7.1-2026-09-04}&quot;">​</a></h2><ul><li>Allowed <code>HypothesisTests</code> 0.12 <a href="https://github.com/PumasAI/SummaryTables.jl/pull/158" target="_blank" rel="noreferrer">#158</a>.</li></ul><h2 id="3.7.0-2026-09-03" tabindex="-1">3.7.0 - 2026-09-03 <a class="header-anchor" href="#3.7.0-2026-09-03" aria-label="Permalink to &quot;3.7.0 - 2026-09-03 {#3.7.0-2026-09-03}&quot;">​</a></h2><ul><li><p>Added <code>Table</code> settings <code>outer_rule_width</code>, <code>inner_rule_width</code>, <code>cell_rule_width</code>, <code>column_padding</code>, <code>row_padding</code>, <code>footnote_size</code> and <code>footnote_halign</code> (also available as global defaults), using font-relative (<code>em</code>) or absolute (<code>pt</code>) lengths that render consistently across all backends; <code>to_docx</code> gained an optional <code>DocxDefaults</code> argument whose <code>base_fontsize</code> resolves relative lengths for Word <a href="https://github.com/PumasAI/SummaryTables.jl/pull/155" target="_blank" rel="noreferrer">#155</a>.</p></li><li><p>The cell <code>indent</code> and the <code>rowgaps</code>/<code>colgaps</code> values now accept <code>em</code> and <code>pt</code> lengths (bare numbers still mean points); the <code>indent_pt</code> keyword is deprecated in favor of <code>indent</code> <a href="https://github.com/PumasAI/SummaryTables.jl/pull/155" target="_blank" rel="noreferrer">#155</a>.</p></li></ul><h2 id="3.6.1-2026-08-07" tabindex="-1">3.6.1 - 2026-08-07 <a class="header-anchor" href="#3.6.1-2026-08-07" aria-label="Permalink to &quot;3.6.1 - 2026-08-07 {#3.6.1-2026-08-07}&quot;">​</a></h2><ul><li>Fixed misalignment of <code>overview_table</code> category bars in HTML output when the environment overrides the table&#39;s line-height <a href="https://github.com/PumasAI/SummaryTables.jl/pull/152" target="_blank" rel="noreferrer">#152</a>.</li></ul><h2 id="3.6.0-2026-08-06" tabindex="-1">3.6.0 - 2026-08-06 <a class="header-anchor" href="#3.6.0-2026-08-06" aria-label="Permalink to &quot;3.6.0 - 2026-08-06 {#3.6.0-2026-08-06}&quot;">​</a></h2><ul><li><p>The category bars in <code>overview_table</code>&#39;s HTML, typst and latex output now line up with the corresponding text lines <a href="https://github.com/PumasAI/SummaryTables.jl/pull/149" target="_blank" rel="noreferrer">#149</a>.</p></li><li><p>Added <code>NumberFormat</code> for formatting numbers per value, per column (<code>simple_table</code>), per variable (<code>listingtable</code>) or per table, with new settings for prefixes and suffixes, scaling, display limits like <code>&lt;0.001</code>, magnitude suffixes like <code>5.4K</code> and exponent style <a href="https://github.com/PumasAI/SummaryTables.jl/pull/139" target="_blank" rel="noreferrer">#139</a>.</p><ul><li><p>Exponential notation now renders like <code>1.5 × 10⁶</code> instead of <code>1.5e6</code> by default, which can be changed back with the <code>exponent_style = :e</code> setting.</p></li><li><p>Added the <code>exponent_thresholds</code> setting which controls the range of base 10 exponents that are displayed without exponential notation.</p></li><li><p><code>round_mode = :sigdigits</code> now shows <code>1234</code> as <code>1.23 × 10³</code> instead of <code>1230</code> at 3 digits, so that every displayed digit is a significant one.</p></li><li><p><code>trailing_zeros</code> now defaults to <code>:auto</code>, which means <code>false</code> for <code>round_mode = :auto</code> and <code>true</code> for <code>:digits</code> and <code>:sigdigits</code>, so the exact modes display exactly the requested precision.</p></li><li><p><code>trailing_zeros = true</code> now pads numbers to the requested precision in the <code>:auto</code> and <code>:sigdigits</code> modes, for example <code>1.50</code> at 3 significant digits.</p></li><li><p>Trailing zeros are now also stripped from e-notation mantissas and negative numbers.</p></li></ul></li><li><p>Corrected the <code>annotation_labels</code> docstring which listed the nonexistent <code>:lowercase</code> and <code>:uppercase</code> variants instead of <code>:letters_lower</code> and <code>:letters_upper</code> <a href="https://github.com/PumasAI/SummaryTables.jl/pull/137" target="_blank" rel="noreferrer">#137</a>.</p></li></ul><h2 id="3.5.1-2026-01-23" tabindex="-1">3.5.1 - 2026-01-23 <a class="header-anchor" href="#3.5.1-2026-01-23" aria-label="Permalink to &quot;3.5.1 - 2026-01-23 {#3.5.1-2026-01-23}&quot;">​</a></h2><ul><li><p>Corrected the docstring of <code>table_one</code> which erroneously listed <code>show_testnames</code> and not <code>show_tests</code> <a href="https://github.com/PumasAI/SummaryTables.jl/pull/126" target="_blank" rel="noreferrer">#126</a>.</p></li><li><p>Fixed inconsistent classification of categorical data, now the rules are the same for <code>table_one</code> and <code>overview_table</code>. A numeric column is a column with some non-missing values, all of which are subtypes of <code>Real</code> but not <code>Bool</code>. All other columns are categorical <a href="https://github.com/PumasAI/SummaryTables.jl/pull/126" target="_blank" rel="noreferrer">#126</a>.</p></li></ul><h2 id="3.5.0-2025-12-08" tabindex="-1">3.5.0 - 2025-12-08 <a class="header-anchor" href="#3.5.0-2025-12-08" aria-label="Permalink to &quot;3.5.0 - 2025-12-08 {#3.5.0-2025-12-08}&quot;">​</a></h2><ul><li><p>Simplified typst escaping, all custom rules were removed and text is simply wrapped in <code>&quot;&quot;</code> with <code>\\&quot;</code> as the only escaped character. This avoids bugs where some text is interpreted as special typst markup <a href="https://github.com/PumasAI/SummaryTables.jl/pull/110" target="_blank" rel="noreferrer">#110</a>.</p></li><li><p>Added <code>recursive = false</code> keyword to <code>Replace</code> postprocessor which causes it to recurse into SummaryTables&#39; own wrapper types like <code>Concat</code> and <code>Multiline</code>. <code>ReplaceMissing</code> is set to be recursive by default and is considered a bugfix as the intent was always to replace all missings, not just top-level <a href="https://github.com/PumasAI/SummaryTables.jl/pull/119" target="_blank" rel="noreferrer">#119</a>.</p></li><li><p>Added <code>numeric_default</code> and <code>categorical_default</code> keywords to <code>table_one</code> to change the default analyses for all columns in a table at once. These parameters can also be changed globally with <code>defaults!</code> <a href="https://github.com/PumasAI/SummaryTables.jl/pull/117" target="_blank" rel="noreferrer">#117</a>.</p></li><li><p>All table functions now use the <code>&quot;label&quot;</code> column metadata as a label by default if it&#39;s present. A different key can be set as the default setting <code>label_key</code>, or <code>nothing</code> to disable the feature <a href="https://github.com/PumasAI/SummaryTables.jl/pull/111" target="_blank" rel="noreferrer">#111</a>.</p></li></ul><h2 id="3.4.0-2025-09-26" tabindex="-1">3.4.0 - 2025-09-26 <a class="header-anchor" href="#3.4.0-2025-09-26" aria-label="Permalink to &quot;3.4.0 - 2025-09-26 {#3.4.0-2025-09-26}&quot;">​</a></h2><ul><li>Added global defaults system which allows to override float rounding behavior and annotation label styles, among others <a href="https://github.com/PumasAI/SummaryTables.jl/pull/108" target="_blank" rel="noreferrer">#108</a>.</li></ul><h2 id="3.3.3-2025-07-17" tabindex="-1">3.3.3 - 2025-07-17 <a class="header-anchor" href="#3.3.3-2025-07-17" aria-label="Permalink to &quot;3.3.3 - 2025-07-17 {#3.3.3-2025-07-17}&quot;">​</a></h2><ul><li><p>Fixed internal alignment of <code>Multiline</code> in the LaTeX backend so that it matches the cell alignment <a href="https://github.com/PumasAI/SummaryTables.jl/pull/98" target="_blank" rel="noreferrer">#98</a>.</p></li><li><p>Fixed unintended enumeration markup in <code>overview_table</code> rendered with Typst <a href="https://github.com/PumasAI/SummaryTables.jl/pull/99" target="_blank" rel="noreferrer">#99</a>.</p></li></ul><h2 id="3.3.2-2025-07-16" tabindex="-1">3.3.2 - 2025-07-16 <a class="header-anchor" href="#3.3.2-2025-07-16" aria-label="Permalink to &quot;3.3.2 - 2025-07-16 {#3.3.2-2025-07-16}&quot;">​</a></h2><ul><li>Fixed rendering of concat/styled annotations and footnotes in docx <a href="https://github.com/PumasAI/SummaryTables.jl/pull/97" target="_blank" rel="noreferrer">#97</a>.</li></ul><h2 id="3.3.1-2025-05-23" tabindex="-1">3.3.1 - 2025-05-23 <a class="header-anchor" href="#3.3.1-2025-05-23" aria-label="Permalink to &quot;3.3.1 - 2025-05-23 {#3.3.1-2025-05-23}&quot;">​</a></h2><ul><li>Fixed <code>overview_table</code> in the presence of all-missing columns <a href="https://github.com/PumasAI/SummaryTables.jl/pull/91" target="_blank" rel="noreferrer">#91</a>.</li></ul><h2 id="3.3.0-2025-03-12" tabindex="-1">3.3.0 - 2025-03-12 <a class="header-anchor" href="#3.3.0-2025-03-12" aria-label="Permalink to &quot;3.3.0 - 2025-03-12 {#3.3.0-2025-03-12}&quot;">​</a></h2><ul><li>Added the <code>overview_table</code> function which creates a quick summary of all columns from a tabular data source, styled after the <code>dfSummary</code> function from R&#39;s <code>summarytools</code> package <a href="https://github.com/PumasAI/SummaryTables.jl/pull/85" target="_blank" rel="noreferrer">#85</a>.</li></ul><h2 id="3.2.0-2025-02-24" tabindex="-1">3.2.0 - 2025-02-24 <a class="header-anchor" href="#3.2.0-2025-02-24" aria-label="Permalink to &quot;3.2.0 - 2025-02-24 {#3.2.0-2025-02-24}&quot;">​</a></h2><ul><li>Added <code>Styled</code> struct for partial styling of text within a cell, including bold, italic, underline and text color. Note that you need to add <code>\\usepackage{xcolor}</code> to use colored text in LaTeX. <a href="https://github.com/PumasAI/SummaryTables.jl/pull/84" target="_blank" rel="noreferrer">#84</a>.</li></ul><h2 id="3.1.0-2025-02-20" tabindex="-1">3.1.0 - 2025-02-20 <a class="header-anchor" href="#3.1.0-2025-02-20" aria-label="Permalink to &quot;3.1.0 - 2025-02-20 {#3.1.0-2025-02-20}&quot;">​</a></h2><ul><li><p>Added <code>header</code> function to typst output such that the header section can repeat after page breaks <a href="https://github.com/PumasAI/SummaryTables.jl/pull/79" target="_blank" rel="noreferrer">#79</a>.</p></li><li><p>Added <code>simple_table</code> function for the display of raw tabular data <a href="https://github.com/PumasAI/SummaryTables.jl/pull/76" target="_blank" rel="noreferrer">#76</a>.</p></li><li><p>Changed html output to use a unique id instead of a class for the table so that SummaryTables&#39; CSS takes priority over class-based settings from Documenter and others. This fixes the look of SummaryTables within Documenter dark mode, for example <a href="https://github.com/PumasAI/SummaryTables.jl/pull/77" target="_blank" rel="noreferrer">#77</a>.</p></li></ul><h2 id="3.0.3-2025-01-31" tabindex="-1">3.0.3 - 2025-01-31 <a class="header-anchor" href="#3.0.3-2025-01-31" aria-label="Permalink to &quot;3.0.3 - 2025-01-31 {#3.0.3-2025-01-31}&quot;">​</a></h2><ul><li><p>Added <code>show</code> method for <code>MIME&quot;QuartoNotebookRunner/typst&quot;</code> to support typst directly in the native quarto julia engine <a href="https://github.com/PumasAI/SummaryTables.jl/pull/69" target="_blank" rel="noreferrer">#69</a>.</p></li><li><p>Allowed <code>String</code>s as column identifiers in addition to <code>Symbol</code>s <a href="https://github.com/PumasAI/SummaryTables.jl/pull/63" target="_blank" rel="noreferrer">#63</a>.</p></li><li><p>Made HTML tables dark mode compatible by reusing foreground color for the lines <a href="https://github.com/PumasAI/SummaryTables.jl/pull/62" target="_blank" rel="noreferrer">#62</a>.</p></li></ul><h2 id="3.0.2-2024-11-27" tabindex="-1">3.0.2 - 2024-11-27 <a class="header-anchor" href="#3.0.2-2024-11-27" aria-label="Permalink to &quot;3.0.2 - 2024-11-27 {#3.0.2-2024-11-27}&quot;">​</a></h2><ul><li>Added extra escape characters to Typst <a href="https://github.com/PumasAI/SummaryTables.jl/pull/54" target="_blank" rel="noreferrer">#54</a>.</li></ul><h2 id="3.0.1-2024-10-24" tabindex="-1">3.0.1 - 2024-10-24 <a class="header-anchor" href="#3.0.1-2024-10-24" aria-label="Permalink to &quot;3.0.1 - 2024-10-24 {#3.0.1-2024-10-24}&quot;">​</a></h2><ul><li><p>Added single-argument method to <code>table_one</code> which summarizes all columns in the passed table except those used for grouping <a href="https://github.com/PumasAI/SummaryTables.jl/pull/48" target="_blank" rel="noreferrer">#48</a>.</p></li><li><p>Fixed issue with using <code>missing</code> as a group in <code>table_one</code>. This PR also removes redundant group totals if there&#39;s just one subgroup to do a total over <a href="https://github.com/PumasAI/SummaryTables.jl/pull/47" target="_blank" rel="noreferrer">#47</a>.</p></li></ul><h2 id="3.0.0-2024-09-23" tabindex="-1">3.0.0 - 2024-09-23 <a class="header-anchor" href="#3.0.0-2024-09-23" aria-label="Permalink to &quot;3.0.0 - 2024-09-23 {#3.0.0-2024-09-23}&quot;">​</a></h2><ul><li><p><strong>Breaking</strong> Footnotes are by default separated with linebreaks now. This can be changed by setting the new <code>Table</code> option <code>linebreak_footnotes = false</code> <a href="https://github.com/PumasAI/SummaryTables.jl/pull/34" target="_blank" rel="noreferrer">#34</a>.</p></li><li><p><strong>Breaking</strong> Changed <code>show_overall</code> keyword of <code>table_one</code> to <code>show_total</code>. The name of all total columns was changed from <code>&quot;Overall&quot;</code> to <code>&quot;Total&quot;</code> as well but this can be changed using the new <code>total_name</code> keyword.</p></li><li><p>Added ability to show &quot;Total&quot; statistics for subgroups in <code>table_one</code> <a href="https://github.com/PumasAI/SummaryTables.jl/pull/30" target="_blank" rel="noreferrer">#30</a>.</p></li><li><p>Fixed tagging of header rows in docx output, such that the header section is now repeated across pages as expected <a href="https://github.com/PumasAI/SummaryTables.jl/pull/32" target="_blank" rel="noreferrer">#32</a>.</p></li></ul><h2 id="2.0.2-2024-09-16" tabindex="-1">2.0.2 - 2024-09-16 <a class="header-anchor" href="#2.0.2-2024-09-16" aria-label="Permalink to &quot;2.0.2 - 2024-09-16 {#2.0.2-2024-09-16}&quot;">​</a></h2><ul><li>Fixed issue where cells would not merge if they stored a <code>Multiline</code> value <a href="https://github.com/PumasAI/SummaryTables.jl/pull/29" target="_blank" rel="noreferrer">#29</a>.</li></ul><h2 id="2.0.1-2024-09-16" tabindex="-1">2.0.1 - 2024-09-16 <a class="header-anchor" href="#2.0.1-2024-09-16" aria-label="Permalink to &quot;2.0.1 - 2024-09-16 {#2.0.1-2024-09-16}&quot;">​</a></h2><ul><li>Fixed incorrect order of column group keys in <code>summarytable</code> and <code>listingtable</code> when some row/col group combinations were missing <a href="https://github.com/PumasAI/SummaryTables.jl/pull/25" target="_blank" rel="noreferrer">#25</a>.</li></ul><h2 id="2.0.0-2024-05-03" tabindex="-1">2.0.0 - 2024-05-03 <a class="header-anchor" href="#2.0.0-2024-05-03" aria-label="Permalink to &quot;2.0.0 - 2024-05-03 {#2.0.0-2024-05-03}&quot;">​</a></h2><ul><li><strong>Breaking</strong> Changed generated Typst code to use the native table functionality available starting with Typst v0.11. Visual output should not change.</li></ul>',41)]))}const p=a(r,[["render",i]]);export{m as __pageData,p as default};
